            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">

              <Card title="Tech Stack" description="The best modern web tools.">
                 <ul className="space-y-3 mt-2">
                   {['React 18+', 'TypeScript', 'Tailwind CSS', 'Google GenAI SDK'].map((tech) => (
                     <li key={tech} className="flex items-center text-slate-700">
                       <svg className="h-5 w-5 text-green-500 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                         <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                       </svg>
                       {tech}
                     </li>
                   ))}
                 </ul>
              </Card>

              <Card title="API Connection" description="Test your Gemini API integration immediately.">
                <div className="space-y-4">
                  <div className="bg-slate-900 rounded-lg p-3 min-h-[80px] text-sm font-mono text-green-400 overflow-auto">
                    {status === AppStatus.LOADING ? 'Generating...' : (response || '// API Response will appear here')}
                  </div>
                  <Button 
                    variant="secondary" 
                    className="w-full" 
                    onClick={handleTestApi}
                    isLoading={status === AppStatus.LOADING}
                  >
                    Ping Gemini API
                  </Button>
                </div>
              </Card>

              <Card title="Project Structure" description="Clean architecture patterns.">
                 <div className="font-mono text-sm text-slate-600 bg-slate-100 p-4 rounded-lg">
